1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"sync"
13	)
14	
15	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
16	//
17	//	{"version":1,
18	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
19	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
20	//	 "settlements":[{...一笔成功结算及其当时费率...}],
21	//	 "refunds":[{...一笔成功全额退款...}],
22	//	 "checksum":"<sha256 of the document without checksum>"}
23	//
24	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
25	// checksum 覆盖截断、比特翻转与所有语义编辑。
26	//
27	// refunds 字段缺省（旧版账本没有该字段）即视为空列表：旧文件可直接打开；
28	// 只要账本没有发生退款，写回时该字段继续缺省，读取旧账本不会改写文件。
29	//
30	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
31	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
32	// 不会出现“扣款/退款无记录”或“记录未改余额”的中间状态。
33	const ledgerVersion = 1
34	
35	// 结算结果状态，与命令行输出一一对应，可分别识别。
36	const (
37		StatusSettled         = "settled"              // 成功扣款
38		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
39		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
40		StatusState           = "state_error"          // 非 pending
41		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
42		StatusLimitExceeded   = "limit_exceeded"       // 本次批次该 (账户, 资产) 组合的扣款上限不足
43		StatusInvalid         = "invalid_parameter"
44		StatusStorage         = "storage_error"
45		StatusRefundSuccess   = "refunded"         // 成功全额退回
46		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
47		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
48	)
49	
50	// 拒绝原因。
51	const (
52		reasonEmptyID         = "intent id must not be empty"
53		reasonEmptyAccount    = "account must not be empty"
54		reasonEmptyAsset      = "asset must not be empty"
55		reasonBadAmount       = "amount must be a positive int64"
56		reasonOverflow        = "amount plus fee overflows int64"
57		reasonNotPending      = "intent is not pending"
58		reasonFunds           = "insufficient balance for amount plus fee"
59		reasonLimitExceeded   = "charge limit exceeded for %s/%s: max_charged %d, used %d, this item charges %d"
60		reasonDuplicate       = "duplicate settlement attempt"
61		reasonConflict        = "settlement id conflicts with a different request"
62		reasonEmptyRefundID   = "refund id must not be empty"
63		reasonEmptySettlement = "settlement_id must not be empty"
64		reasonEmptyReason     = "refund reason must not be empty"
65		reasonSettlementGone  = "settlement %q not found"
66		reasonAlreadyRefunded = "settlement %q has already been refunded by %q"
67		reasonRefundConflict  = "refund id conflicts with a different request"
68		reasonDuplicateRefund = "duplicate refund attempt"
69	)
70	
71	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
72	type BalanceInit struct {
73		Account string `json:"account"`
74		Asset   string `json:"asset"`
75		Balance int64  `json:"balance"`
76	}
77	
78	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
79	type PaymentIntent struct {
80		ID        string `json:"id"`
81		Account   string `json:"account"`
82		Paymaster string `json:"paymaster"`
83		Asset     string `json:"asset"`
84		Amount    *int64 `json:"amount"`
85		Nonce     uint64 `json:"nonce"`
86		State     string `json:"state"`
87	}
88	
89	// ChargeLimit 是本次提交中一个 (账户, 资产) 组合的扣款上限：该组合在本批次内
90	// 成功落账的 charged（付款金额 + 手续费）累计不得超过 max_charged。
91	// 上限仅对本次提交有效，不持久化；历史扣款与退款都不占本次额度。
92	// MaxCharged 使用指针以区分“缺省/null”与显式给出的 0（0 表示禁止该组合新增扣款）。
93	type ChargeLimit struct {
94		Account    string `json:"account"`
95		Asset      string `json:"asset"`
96		MaxCharged *int64 `json:"max_charged"`
97	}
98	
99	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表 + 可选的本次扣款上限。
100	// Limits 缺省、为 null 或为空数组时不限制扣款。
101	type FeeBatch struct {
102		FeeBps  int             `json:"fee_bps"`
103		Intents []PaymentIntent `json:"intents"`
104		Limits  []ChargeLimit   `json:"limits,omitempty"`
105	}
106	
107	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
108	type Record struct {
109		ID        string `json:"id"`
110		Account   string `json:"account"`
111		Paymaster string `json:"paymaster"`
112		Asset     string `json:"asset"`
113		Amount    int64  `json:"amount"`
114		Nonce     uint64 `json:"nonce"`
115		FeeBps    int    `json:"fee_bps"`
116		Fee       int64  `json:"fee"`
117		Charged   int64  `json:"charged"`
118		Seq       int64  `json:"seq"`
119	}
120	
121	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
122	type ItemResult struct {
123		ID     string  `json:"id"`
124		Status string  `json:"status"`
125		Reason string  `json:"reason,omitempty"`
126		Record *Record `json:"record,omitempty"`
127	}
128	
129	// BatchResult 是一次提交的结果。空批次对应空 Results。
130	type BatchResult struct {
131		Results []ItemResult `json:"results"`
132	}
133	
134	// PreviewResult 是一次提交预览（--dry-run）的结果。DryRun 恒为 true，
135	// 用于与真实提交输出区分；Results 与输入逐项对应，状态、失败原因与结算
136	// 记录格式与 Submit 完全一致——其中 settled 表示“按当前账本预计能够成功”，
137	// 携带的记录使用从当前最大付款序号之后连续递增的预计序号。
138	// 预览不写入账本，序号、余额与本批次额度都不会被预留。
139	type PreviewResult struct {
140		DryRun  bool         `json:"dry_run"`
141		Results []ItemResult `json:"results"`
142	}
143	
144	// RefundRequest 是退款批次中的一项：退款编号、原付款编号、退款原因，三者均须非空。
145	type RefundRequest struct {
146		ID           string `json:"id"`
147		SettlementID string `json:"settlement_id"`
148		Reason       string `json:"reason"`
149	}
150	
151	// RefundBatch 是一次退款提交：有序的退款请求列表。
152	type RefundBatch struct {
153		Refunds []RefundRequest `json:"refunds"`
154	}
155	
156	// RefundRecord 是一笔成功全额退款留下的永久记录，按退款成功先后顺序保存。
157	// 退款金额与去向（账户/资产/总额）全部由原结算记录确定，因此一并冗余记录，
158	// 使每条退款都能脱离上下文自解释、可追溯原结算。
159	// AfterSeq 是退款落账时结算历史的长度：余额校验要求该结算在此时点之前发生。
160	type RefundRecord struct {
161		ID           string `json:"id"`
162		SettlementID string `json:"settlement_id"`
163		Reason       string `json:"reason"`
164		Account      string `json:"account"`
165		Asset        string `json:"asset"`
166		Amount       int64  `json:"amount"`
167		Fee          int64  `json:"fee"`
168		Charged      int64  `json:"charged"`
169		AfterSeq     int64  `json:"after_seq"`
170		Seq          int64  `json:"seq"`
171	}
172	
173	// RefundResult 是一项退款的处理结果。成功与幂等重复携带原付款编号、账户、
174	// 资产、退款总额与原因；失败只带状态与说明。
175	type RefundResult struct {
176		ID           string        `json:"id"`
177		Status       string        `json:"status"`
178		Reason       string        `json:"reason,omitempty"`
179		SettlementID string        `json:"settlement_id,omitempty"`
180		Account      string        `json:"account,omitempty"`
181		Asset        string        `json:"asset,omitempty"`
182		Charged      int64         `json:"charged,omitempty"`
183		Record       *RefundRecord `json:"record,omitempty"`
184	}
185	
186	// RefundBatchResult 是一次退款提交的结果，顺序与输入逐项对应。
187	type RefundBatchResult struct {
188		Results []RefundResult `json:"results"`
189	}
190	
191	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
192	type BalanceView struct {
193		Account string `json:"account"`
194		Asset   string `json:"asset"`
195		Balance int64  `json:"balance"`
196	}
197	
198	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
199	type Snapshot struct {
200		Balances    []BalanceView  `json:"balances"`
201		Settlements []Record       `json:"settlements"`
202		Refunds     []RefundRecord `json:"refunds"`
203	}
204	
205	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
206	type LedgerError struct {
207		Kind    string
208		Message string
209	}
210	
211	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
212	
213	// 错误分类。
214	const (
215		ErrInvalid = "invalid_parameter"
216		ErrExists  = "ledger_exists"
217		ErrCorrupt = "corrupt_ledger"
218		ErrStorage = "storage_error"
219		ErrClosed  = "ledger_closed"
220		ErrNotInit = "ledger_not_initialized"
221	)
222	
223	func ledgerError(kind, format string, args ...any) error {
224		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
225	}
226	
227	// KindOf 返回错误的分类；非账本错误按存储错误处理。
228	func KindOf(err error) string {
229		var le *LedgerError
230		if errors.As(err, &le) {
231			return le.Kind
232		}
233		return ErrStorage
234	}
235	
236	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
237	// 内存状态必须回滚到该项执行之前。仅用于测试。
238	type FailWriter interface {
239		FailNextPersist() bool
240	}
241	
242	type balanceKey struct {
243		account string
244		asset   string
245	}
246	
247	type ledgerState struct {
248		Version     int
249		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
250		Balances    map[balanceKey]int64 // 当前余额
251		Settlements []Record
252		Refunds     []RefundRecord
253	}
254	
255	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
256	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
257	// 且无退款的账本写回时继续省略该字段。
258	type unsignedDoc struct {
259		Version     int            `json:"version"`
260		Initial     []BalanceView  `json:"initial_balances"`
261		Balances    []BalanceView  `json:"balances"`
262		Settlements []Record       `json:"settlements"`
263		Refunds     []RefundRecord `json:"refunds,omitempty"`
264	}
265	
266	type signedDoc struct {
267		unsignedDoc
268		Checksum string `json:"checksum"`
269	}
270	
271	func balanceList(m map[balanceKey]int64) []BalanceView {
272		out := make([]BalanceView, 0, len(m))
273		for k, v := range m {
274			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
275		}
276		sortBalances(out)
277		return out
278	}
279	
280	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
281		out := make(map[balanceKey]int64, len(list))
282		for i, b := range list {
283			if b.Account == "" || b.Asset == "" {
284				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
285			}
286			if b.Balance < 0 {
287				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
288			}
289			k := balanceKey{b.Account, b.Asset}
290			if _, dup := out[k]; dup {
291				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
292			}
293			out[k] = b.Balance
294		}
295		return out, nil
296	}
297	
298	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
299	func (s *ledgerState) MarshalJSON() ([]byte, error) {
300		settlements := s.Settlements
301		if settlements == nil {
302			settlements = []Record{}
303		}
304		doc := unsignedDoc{
305			Version:     s.Version,
306			Initial:     balanceList(s.Initial),
307			Balances:    balanceList(s.Balances),
308			Settlements: settlements,
309			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
310		}
311		payload, err := json.Marshal(doc)
312		if err != nil {
313			return nil, err
314		}
315		sum := checksumHex(payload)
316		out := make([]byte, 0, len(payload)+len(sum)+16)
317		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
318		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
319		return out, nil
320	}
321	
322	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
323	func (s *ledgerState) UnmarshalJSON(data []byte) error {
324		var doc signedDoc
325		if err := json.Unmarshal(data, &doc); err != nil {
326			return err
327		}
328		if doc.Checksum == "" {
329			return ledgerError(ErrCorrupt, "missing checksum")
330		}
331		payload, err := json.Marshal(doc.unsignedDoc)
332		if err != nil {
333			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
334		}
335		if got := checksumHex(payload); got != doc.Checksum {
336			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
337		}
338		if doc.Version != ledgerVersion {
339			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
340		}
341		initial, err := balanceMap(doc.Initial)
342		if err != nil {
343			return err
344		}
345		current, err := balanceMap(doc.Balances)
346		if err != nil {
347			return err
348		}
349		records := doc.Settlements
350		if records == nil {
351			records = []Record{}
352		}
353		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
354		if refunds == nil {
355			refunds = []RefundRecord{}
356		}
357		if err := validateAndReplay(initial, current, records, refunds); err != nil {
358			return err
359		}
360		s.Version = doc.Version
361		s.Initial = initial
362		s.Balances = current
363		s.Settlements = records
364		s.Refunds = refunds
365		return nil
366	}
367	
368	func decodeState(data []byte) (*ledgerState, error) {
369		var state ledgerState
370		if err := json.Unmarshal(data, &state); err != nil {
371			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
372				return nil, err
373			}
374			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
375		}
376		return &state, nil
377	}
378	
379	// canonicalLedgerPath 把绝对路径解析为账本的规范路径：解析目录与文件本身
380	// 的符号链接，使同一账本经不同路径（如指向账本所在目录的软链接）打开时
381	// 共享同一注册表项、同一份内存状态与互斥锁。账本文件尚不存在时（未初始化）
382	// 解析其父目录；父目录也无法解析时退回原路径。
383	func canonicalLedgerPath(abs string) string {
384		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
385			return resolved
386		}
387		if resolved, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
388			return filepath.Join(resolved, filepath.Base(abs))
389		}
390		return abs
391	}
392	
393	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
394	// 任一不合法则返回 ErrInvalid 且不创建任何文件。
395	//
396	// “路径是否占用”与“创建账本”由内核一步原子完成（见 createExclusive）：
397	//   - 路径上已有正常账本、损坏或空的普通文件、目录：返回 ErrExists，
398	//     原内容逐字节不变；
399	//   - 账本文件位置上是符号链接时（无论链接指向文件还是目录、目标是否
400	//     存在）：返回 ErrExists，链接本身与其去向都不变，也不会顺着悬空
401	//     链接把目标文件创建出来；
402	//   - 经指向目录的符号链接访问一个尚未占用的文件位置时创建照常成功。
403	//
404	// 因此多个进程同时初始化同一尚不存在的账本（包括一方经真实目录、
405	// 另一方经指向该目录的符号链接访问同一目标）时，恰好一个成功，
406	// 其余返回 ErrExists，磁盘上完整保留胜出方的初始余额，绝不覆盖历史。
407	// 已有句柄打开（或有在途操作）的路径同样拒绝初始化。
408	func CreateLedger(path string, init []BalanceInit) error {
409		if err := validateInitial(init); err != nil {
410			return err
411		}
412		abs, err := filepath.Abs(path)
413		if err != nil {
414			return ledgerError(ErrStorage, "resolve path: %v", err)
415		}
416	
417		openMu.Lock()
418		defer openMu.Unlock()
419	
420		// 注册表按规范路径索引（父目录符号链接解析到真实目录），与 Open 一致。
421		// 注意 canonicalLedgerPath 对悬空符号链接只解析到其父目录、basename
422		// 仍是链接名；而下面的发布操作刻意使用字面 abs 而非该解析结果，确保
423		// 账本位置本身是符号链接时由内核原子拒绝，绝不顺着链接创建目标。
424		if openRegistry[canonicalLedgerPath(abs)] != nil {
425			// 已有句柄打开（或有在途操作）的路径不能再初始化：即便文件恰好被
426			// 外部删除，也不能用一本新账顶替正在使用的账本。
427			return ledgerError(ErrExists, "ledger is already initialized in this process")
428		}
429	
430		// 账本是否存在、内容是否完好一律以磁盘的原子创建结果为准；
431		// CreateLedger 不预登记内存状态，首次 Open 必须实际读取并校验该文件。
432		state := &ledgerState{
433			Version:     ledgerVersion,
434			Initial:     make(map[balanceKey]int64, len(init)),
435			Balances:    make(map[balanceKey]int64, len(init)),
436			Settlements: []Record{},
437			Refunds:     []RefundRecord{},
438		}
439		for _, b := range init {
440			k := balanceKey{b.Account, b.Asset}
441			state.Initial[k] = b.Balance
442			state.Balances[k] = b.Balance
443		}
444		// 发布使用字面绝对路径：父目录中的符号链接照常解析（允许经目录软链接
445		// 在尚未占用的文件位置创建新账本），账本位置本身的符号链接则被
446		// link(2) 原子拒绝；占用竞争失败返回 ErrExists，写入故障返回
447		// ErrStorage，两种情况下路径上都不会留下半成品。
448		if err := createExclusive(abs, state); err != nil {
449			return err
450		}
451		// 不登记 openRegistry：尚未有任何句柄，首次 Open 必须以磁盘文件为准，
452		// 这样在初始化与首次打开之间删除、清空或篡改文件都会被如实发现。
453		return nil
454	}
455	
456	func validateInitial(init []BalanceInit) error {
457		seen := map[balanceKey]bool{}
458		for i, b := range init {
459			if b.Account == "" {
460				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
461			}
462			if b.Asset == "" {
463				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
464			}
465			if b.Balance < 0 {
466				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
467			}
468			k := balanceKey{b.Account, b.Asset}
469			if seen[k] {
470				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
471			}
472			seen[k] = true
473		}
474		return nil
475	}
476	
477	// Ledger 是一个可持久化的本地账本。同一进程内指向同一账本文件的多次 Open
478	// （包括经目录软链接的不同路径）返回共享同一状态与互斥锁的实例，
479	// 因此并发提交按同一本账本串行化。
480	type Ledger struct {
481		path string
482		reg  *registryEntry
483		open bool
484	}
485	
486	type registryEntry struct {
487		mu       sync.Mutex // 保护 state；整个批次串行持有
488		state    *ledgerState
489		holders  map[*Ledger]struct{} // 当前打开的句柄
490		ops      int                  // 正在执行的 Submit/Query 数（含已关闭句柄的在途操作）
491		failHook FailWriter           // 仅测试注入
492	}
493	
494	// alive 报告该注册表项是否仍须保留：至少还有一个打开的句柄，或一个
495	// （可能来自已关闭句柄的）在途操作。全为零时该项可被注销，此后的 Open
496	// 重新以磁盘文件为准。
497	// 调用方必须持有 openMu。
498	func (r *registryEntry) alive() bool {
499		return len(r.holders) > 0 || r.ops > 0
500	}
501	
502	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
503	// 调用方必须持有 openMu。
504	func tryEvict(path string, reg *registryEntry) {
505		if !reg.alive() && openRegistry[path] == reg {
506			delete(openRegistry, path)
507		}
508	}
509	
510	var (
511		openMu       sync.Mutex
512		openRegistry = map[string]*registryEntry{}
513	)
514	
515	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
516	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
517	func Open(path string) (*Ledger, error) {
518		abs, err := filepath.Abs(path)
519		if err != nil {
520			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
521		}
522		abs = canonicalLedgerPath(abs)
523	
524		openMu.Lock()
525		defer openMu.Unlock()
526	
527		if reg := openRegistry[abs]; reg != nil {
528			// 同进程已有句柄（或在途操作）承接该账本：共享当前完整状态，不重新读盘。
529			// 注册表项只在存在活动句柄/在途操作期间保留，因此走到这里时磁盘文件
530			// 的状态已不再权威——例如它可能正被一笔在途付款以原子写替换。
531			h := &Ledger{path: abs, reg: reg, open: true}
532			reg.holders[h] = struct{}{}
533			return h, nil
534		}
535	
536		data, err := os.ReadFile(abs)
537		if err != nil {
538			if errors.Is(err, os.ErrNotExist) {
539				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
540			}
541			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
542		}
543		if len(bytes.TrimSpace(data)) == 0 {
544			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
545		}
546		dec := json.NewDecoder(bytes.NewReader(data))
547		var rawDoc json.RawMessage
548		if err := dec.Decode(&rawDoc); err != nil {
549			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
550		}
551		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
552		if tok, err := dec.Token(); err != io.EOF {
553			if err == nil {
554				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
555			}
556			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
557		}
558		state, err := decodeState(rawDoc)
559		if err != nil {
560			return nil, err
561		}
562	
563		reg := &registryEntry{state: state, holders: map[*Ledger]struct{}{}}
564		h := &Ledger{path: abs, reg: reg, open: true}
565		reg.holders[h] = struct{}{}
566		openRegistry[abs] = reg
567		return h, nil
568	}
569	
570	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
571	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
572	// 从磁盘重新加载而丢失正在写入的状态。
573	func (l *Ledger) Close() error {
574		openMu.Lock()
575		defer openMu.Unlock()
576		if !l.open {
577			return nil
578		}
579		l.open = false
580		delete(l.reg.holders, l)
581		tryEvict(l.path, l.reg)
582		return nil
583	}
584	
585	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
586	func (l *Ledger) beginOp() error {
587		openMu.Lock()
588		defer openMu.Unlock()
589		if !l.open {
590			return ledgerError(ErrClosed, "ledger handle is closed")
591		}
592		l.reg.ops++
593		return nil
594	}
595	
596	func (l *Ledger) endOp() {
597		openMu.Lock()
598		defer openMu.Unlock()
599		l.reg.ops--
600		tryEvict(l.path, l.reg)
601	}
602	
603	// 付款金额、费率、手续费与扣款总额的数值规则集中在 charge.go
604	// （amountValid/feeBpsValid/feeFor/chargeFor），本地结算、遗留单笔结算
605	// 与账本历史校验共用同一实现。
606	
607	func validateIntent(it PaymentIntent) (int64, string, bool) {
608		if it.ID == "" {
609			return 0, reasonEmptyID, false
610		}
611		if it.Account == "" {
612			return 0, reasonEmptyAccount, false
613		}
614		if it.Asset == "" {
615			return 0, reasonEmptyAsset, false
616		}
617		if it.Amount == nil || !amountValid(*it.Amount) {
618			return 0, reasonBadAmount, false
619		}
620		return *it.Amount, "", true
621	}
622	
623	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
624	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
625	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
626	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
627		if len(limits) == 0 {
628			return nil, nil
629		}
630		out := make(map[balanceKey]int64, len(limits))
631		for i, l := range limits {
632			if l.Account == "" {
633				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
634			}
635			if l.Asset == "" {
636				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
637			}
638			if l.MaxCharged == nil {
639				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
640			}
641			if *l.MaxCharged < 0 {
642				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
643			}
644			k := balanceKey{l.Account, l.Asset}
645			if _, dup := out[k]; dup {
646				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
647			}
648			out[k] = *l.MaxCharged
649		}
650		return out, nil
651	}
652	
653	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
654	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
655	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
656	//
657	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
658	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
659	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
660	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
661	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
662		if err := l.beginOp(); err != nil {
663			return nil, err
664		}
665		defer l.endOp()
666		limits, err := validateBatch(batch)
667		if err != nil {
668			return nil, err
669		}
670	
671		l.reg.mu.Lock()
672		defer l.reg.mu.Unlock()
673	
674		results := runBatch(batch, limits, l.reg.state, l.persistEffect)
675		return &BatchResult{Results: results}, nil
676	}
677	
678	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
679	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
680	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
681	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
682	//     失败、重复、冲突不消耗序号；
683	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
684	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
685	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
686	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
687	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
688	//
689	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
690	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
691	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
692	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
693	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
694	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
695		if err := l.beginOp(); err != nil {
696			return nil, err
697		}
698		defer l.endOp()
699		limits, err := validateBatch(batch)
700		if err != nil {
701			return nil, err
702		}
703	
704		l.reg.mu.Lock()
705		defer l.reg.mu.Unlock()
706	
707		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
708		sim := cloneState(l.reg.state)
709		results := runBatch(batch, limits, sim, simulateEffect)
710		return &PreviewResult{DryRun: true, Results: results}, nil
711	}
712	
713	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
714	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
715	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
716		if !feeBpsValid(batch.FeeBps) {
717			return nil, ledgerError(ErrInvalid, "%s", reasonBadFeeBps(batch.FeeBps))
718		}
719		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
720		return validateLimits(batch.Limits)
721	}
722	
723	// ledgerEffect 是一笔预计成功落账（付款扣款或退款退回）的全部账本效果：
724	// 变动哪个组合、余额增减多少、向哪一类成功历史追加什么记录。delta 为正
725	// 表示增加余额（退款），为负表示减少余额（付款扣款）。它由各自的业务规则
726	// 产生，本身尚未生效；是否生效、如何生效（真实落盘或预览模拟）由生效策略
727	// 决定。付款与退款共用这一个效果结构，因此“改余额 + 追加成功记录 +
728	// 保存失败恢复原状”的落账步骤只需在 applyEffect 一处维护。
729	type ledgerEffect struct {
730		key      balanceKey
731		delta    int64
732		settling *Record       // 付款成功时追加到结算历史；退款时为 nil
733		refund   *RefundRecord // 退款成功时追加到退款历史；付款时为 nil
734	}
735	
736	// applyEffect 把一笔预计成功的落账效果应用到状态 st：余额变动与对应成功
737	// 记录在同一步完成，查询不会看到只有余额变化而没有记录的状态。返回回滚
738	// 函数，恢复该项执行前的余额与对应历史长度（只撤销该项自己的变化，
739	// 不动另一类历史、不动之前已成功的记录）。付款与退款的落账与回滚都走
740	// 这一个出口。
741	func applyEffect(st *ledgerState, eff ledgerEffect) func() {
742		oldBal, hadKey := st.Balances[eff.key]
743		st.Balances[eff.key] = oldBal + eff.delta
744	
745		var oldSettlements, oldRefunds int
746		if eff.settling != nil {
747			oldSettlements = len(st.Settlements)
748			st.Settlements = append(st.Settlements, *eff.settling)
749		} else {
750			oldRefunds = len(st.Refunds)
751			st.Refunds = append(st.Refunds, *eff.refund)
752		}
753	
754		return func() {
755			if hadKey {
756				st.Balances[eff.key] = oldBal
757			} else {
758				delete(st.Balances, eff.key)
759			}
760			if eff.settling != nil {
761				st.Settlements = st.Settlements[:oldSettlements]
762			} else {
763				st.Refunds = st.Refunds[:oldRefunds]
764			}
765		}
766	}
767	
768	// commitEffect 是落账生效策略：把一笔预计成功的效果应用到状态 st 上。
769	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
770	// 该项执行之前的余额与历史。
771	type commitEffect func(st *ledgerState, eff ledgerEffect) error
772	
773	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
774	// 付款规则（judgeIntent）与落账生效（commit）分离：规则只读取 st 与
775	// 本批次已用额度给出判定和预计落账效果，不改动任何状态；生效策略决定
776	// 效果如何落地——真实提交先改内存再原子落盘、失败回滚并报告
777	// storage_error，预览只在副本上推进内存状态、绝不落盘。两种操作共用
778	// 同一份规则，因此逐项判定完全一致。调用方必须持有 reg.mu。
779	func runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, commit commitEffect) []ItemResult {
780		out := make([]ItemResult, 0, len(batch.Intents))
781	
782		// 本次批次内各组合已消耗的额度，从零开始，仅成功生效的扣款计入。
783		used := make(map[balanceKey]int64, len(limits))
784	
785		for i := range batch.Intents {
786			it := &batch.Intents[i]
787	
788			// 1. 规则判定：纯读取，不产生任何副作用。
789			res, eff := judgeIntent(it, batch.FeeBps, limits, used, st)
790			if eff == nil {
791				out = append(out, res)
792				continue
793			}
794	
795			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
796			//    该项报告 storage_error，不留记录、不占额度，后项继续处理。
797			if err := commit(st, *eff); err != nil {
798				res.Status = StatusStorage
799				res.Reason = err.Error()
800				out = append(out, res)
801				continue
802			}
803	
804			// 3. 只有成功生效的扣款才消耗本批次额度（预览同样如此）。
805			used[eff.key] += -eff.delta
806			cp := *eff.settling
807			res.Status = StatusSettled
808			res.Record = &cp
809			out = append(out, res)
810		}
811		return out
812	}
813	
814	// judgeIntent 按付款规则评估一项请求，只读取状态与额度用量，不产生副作用。
815	// 返回逐项结果；预计成功时结果只填编号，落账效果以 ledgerEffect 描述，
816	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功编号的
817	// 重复/冲突、状态、溢出、本批次限额（先于余额）、余额。
818	func judgeIntent(it *PaymentIntent, feeBps int, limits map[balanceKey]int64, used map[balanceKey]int64, st *ledgerState) (ItemResult, *ledgerEffect) {
819		res := ItemResult{ID: it.ID}
820	
821		// 1. 参数校验。未通过的编号不占用去重资格。
822		amount, reason, ok := validateIntent(*it)
823		if !ok {
824			res.Status = StatusInvalid
825			res.Reason = reason
826			return res, nil
827		}
828	
829		// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
830		//    任一不同则编号冲突。两者都不再扣款、不改原记录。
831		//    本批次内先（预计）成功的同编号项也在此被看到。
832		if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
833			if sameRequest(rec, it, amount, feeBps) {
834				cp := rec
835				res.Status = StatusDuplicate
836				res.Reason = reasonDuplicate
837				res.Record = &cp
838			} else {
839				res.Status = StatusConflict
840				res.Reason = reasonConflict
841			}
842			return res, nil
843		}
844	
845		// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
846		if it.State != "" && it.State != "pending" {
847			res.Status = StatusState
848			res.Reason = reasonNotPending
849			return res, nil
850		}
851	
852		// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
853		fee, total, ok := chargeFor(amount, feeBps)
854		if !ok {
855			res.Status = StatusInvalid
856			res.Reason = reasonOverflow
857			return res, nil
858		}
859	
860		key := balanceKey{it.Account, it.Asset}
861	
862		// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
863		//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
864		//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
865		if max, capped := limits[key]; capped {
866			if u := used[key]; total > max-u {
867				res.Status = StatusLimitExceeded
868				res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
869				return res, nil
870			}
871		}
872	
873		// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
874		if total > st.Balances[key] {
875			res.Status = StatusFunds
876			res.Reason = reasonFunds
877			return res, nil
878		}
879	
880		// 7. 预计成功：描述落账效果（余额扣减总额、序号按当前结算历史长度
881		//    连续递增）。
882		rec := Record{
883			ID:        it.ID,
884			Account:   it.Account,
885			Paymaster: it.Paymaster,
886			Asset:     it.Asset,
887			Amount:    amount,
888			Nonce:     it.Nonce,
889			FeeBps:    feeBps,
890			Fee:       fee,
891			Charged:   total,
892			Seq:       int64(len(st.Settlements)) + 1,
893		}
894		return res, &ledgerEffect{
895			key:      key,
896			delta:    -total,
897			settling: &rec,
898		}
899	}
900	
901	// simulateEffect 是预览的生效策略：只在（副本）状态上推进余额与对应
902	// 历史，绝不触碰磁盘，因此不会失败，预览结果中也不会出现 storage_error。
903	func simulateEffect(st *ledgerState, eff ledgerEffect) error {
904		applyEffect(st, eff)
905		return nil
906	}
907	
908	// persistEffect 是真实落账（付款与退款共用）的生效策略：先在内存生效
909	// （余额变动与成功记录同一步完成），再原子落盘；落盘失败回滚该项
910	// （applyEffect 返回的回滚恢复余额与对应历史），并返回存储错误。
911	func (l *Ledger) persistEffect(st *ledgerState, eff ledgerEffect) error {
912		rollback := applyEffect(st, eff)
913		if err := l.persistLocked(); err != nil {
914			rollback()
915			return err
916		}
917		return nil
918	}
919	
920	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
921	func cloneState(st *ledgerState) *ledgerState {
922		cp := &ledgerState{
923			Version:     st.Version,
924			Initial:     make(map[balanceKey]int64, len(st.Initial)),
925			Balances:    make(map[balanceKey]int64, len(st.Balances)),
926			Settlements: append([]Record(nil), st.Settlements...),
927			Refunds:     append([]RefundRecord(nil), st.Refunds...),
928		}
929		for k, v := range st.Initial {
930			cp.Initial[k] = v
931		}
932		for k, v := range st.Balances {
933			cp.Balances[k] = v
934		}
935		return cp
936	}
937	
938	// findRecordIn 在给定结算历史中按编号查找成功记录。
939	func findRecordIn(records []Record, id string) (Record, bool) {
940		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
941		for _, r := range records {
942			if r.ID == id {
943				return r, true
944			}
945		}
946		return Record{}, false
947	}
948	
949	// validateRefundRequest 校验一项退款请求：退款编号、原付款编号、原因三者
950	// 都必须非空，校验顺序即对外约定（id → settlement_id → reason）。
951	// 未通过校验的编号不占用退款资格，之后可修改后重新提交。
952	func validateRefundRequest(req *RefundRequest) (string, bool) {
953		if req.ID == "" {
954			return reasonEmptyRefundID, false
955		}
956		if req.SettlementID == "" {
957			return reasonEmptySettlement, false
958		}
959		if req.Reason == "" {
960			return reasonEmptyReason, false
961		}
962		return "", true
963	}
964	
965	// attachRefundDetail 把一笔成功退款（首次成功或幂等重复携带的同一条原记录）
966	// 的统一详情填入逐项结果：原付款编号、账户、资产、退款总额、原因与完整退款
967	// 记录。首次成功与重复申请共用这一个出口，保证两者拼装出的详情逐字一致。
968	func attachRefundDetail(res *RefundResult, rec RefundRecord) {
969		res.Reason = rec.Reason
970		res.SettlementID = rec.SettlementID
971		res.Account = rec.Account
972		res.Asset = rec.Asset
973		res.Charged = rec.Charged
974		cp := rec
975		res.Record = &cp
976	}
977	
978	// judgeRefund 按退款规则评估一项请求，只读取状态 st，不产生任何副作用。
979	// 返回逐项结果；预计成功时结果只填编号，落账效果以 ledgerEffect 描述，
980	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功退款编号
981	// 的重复/冲突（优先于目标判断，即使新目标不存在也不退化成 not_found）、
982	// 目标结算存在性、目标是否已被其他退款编号退回。
983	func judgeRefund(req *RefundRequest, st *ledgerState) (RefundResult, *ledgerEffect) {
984		res := RefundResult{ID: req.ID}
985	
986		// 1. 参数校验。未通过的编号不占用退款资格。
987		if reason, ok := validateRefundRequest(req); !ok {
988			res.Status = StatusInvalid
989			res.Reason = reason
990			return res, nil
991		}
992	
993		// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
994		//    任一不同则冲突（即使新目标不存在也不能退化成 not_found）。
995		//    两者都不再入账。本批次内先成功的同编号项也在此被看到。
996		if prior, exists := findRefundIn(st.Refunds, req.ID); exists {
997			if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
998				res.Status = StatusDuplicate
999				attachRefundDetail(&res, prior)
1000			} else {
1001				res.Status = StatusConflict
1002				res.Reason = reasonRefundConflict
1003			}
1004			return res, nil
1005		}
1006	
1007		// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
1008		target, exists := findRecordIn(st.Settlements, req.SettlementID)
1009		if !exists {
1010			res.Status = StatusNotFound
1011			res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
1012			return res, nil
1013		}
1014	
1015		// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
1016		if prior, refunded := findRefundOfSettlementIn(st.Refunds, req.SettlementID); refunded {
1017			res.Status = StatusAlreadyRefunded
1018			res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
1019			return res, nil
1020		}
1021	
1022		// 5. 预计成功：全额（amount 与当时手续费一并，即以原结算的 charged 为准）
1023		//    退回原账户、原资产；序号按当前退款历史长度连续递增。
1024		rec := RefundRecord{
1025			ID:           req.ID,
1026			SettlementID: target.ID,
1027			Reason:       req.Reason,
1028			Account:      target.Account,
1029			Asset:        target.Asset,
1030			Amount:       target.Amount,
1031			Fee:          target.Fee,
1032			Charged:      target.Charged,
1033			AfterSeq:     int64(len(st.Settlements)),
1034			Seq:          int64(len(st.Refunds)) + 1,
1035		}
1036		return res, &ledgerEffect{
1037			key:    balanceKey{target.Account, target.Asset},
1038			delta:  target.Charged,
1039			refund: &rec,
1040		}
1041	}
1042	
1043	// runRefundBatch 按输入顺序在给定状态 st 上处理整个退款批次，返回逐项结果。
1044	// 退款规则（judgeRefund）与落账生效（commit）分离：规则只读取 st 给出判定
1045	// 和预计落账效果，不改动任何状态；生效策略与付款提交共用同一套
1046	// applyEffect/落盘/回滚步骤——真实提交先改内存再原子落盘、失败回滚并报告
1047	// storage_error。保存失败时 commit 已回滚该项（余额与退款历史恢复原样），
1048	// 该项不占退款编号、不把原付款标成已退款，前项成功保留、后项继续处理。
1049	// 调用方必须持有 reg.mu。
1050	func runRefundBatch(batch RefundBatch, st *ledgerState, commit commitEffect) []RefundResult {
1051		out := make([]RefundResult, 0, len(batch.Refunds))
1052		for i := range batch.Refunds {
1053			req := &batch.Refunds[i]
1054	
1055			// 1. 规则判定：纯读取，不产生任何副作用。
1056			res, eff := judgeRefund(req, st)
1057			if eff == nil {
1058				out = append(out, res)
1059				continue
1060			}
1061	
1062			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
1063			//    该项报告 storage_error，不留退款记录、不占退款序号，后项继续。
1064			if err := commit(st, *eff); err != nil {
1065				res.Status = StatusStorage
1066				res.Reason = err.Error()
1067				out = append(out, res)
1068				continue
1069			}
1070	
1071			// 3. 成功落账：与重复申请一样通过统一出口拼装详情。
1072			res.Status = StatusRefundSuccess
1073			attachRefundDetail(&res, *eff.refund)
1074			out = append(out, res)
1075		}
1076		return out
1077	}
1078	
1079	// findRefundIn 在给定退款历史中按编号查找成功记录。
1080	func findRefundIn(refunds []RefundRecord, id string) (RefundRecord, bool) {
1081		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1082		for _, r := range refunds {
1083			if r.ID == id {
1084				return r, true
1085			}
1086		}
1087		return RefundRecord{}, false
1088	}
1089	
1090	// findRefundOfSettlementIn 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1091	func findRefundOfSettlementIn(refunds []RefundRecord, settlementID string) (RefundRecord, bool) {
1092		for _, r := range refunds {
1093			if r.SettlementID == settlementID {
1094				return r, true
1095			}
1096		}
1097		return RefundRecord{}, false
1098	}
1099	
1100	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
1101	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
1102	// 结果与输入逐项对应，空批次返回空结果。
1103	//
1104	// 语义：
1105	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
1106	//     及原退款记录（不再入账）；任一不同返回 conflict（即使新目标不存在也一样，
1107	//     不能退化成 not_found）。
1108	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
1109	//     该结算已被其他退款编号退回返回 already_refunded，不增加余额。
1110	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
1111	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
1112	//   - 失败申请（参数错误、目标不存在、已退款、冲突、存储错误）不占用退款编号，
1113	//     之后可修改原因或目标再提交。
1114	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
1115		if err := l.beginOp(); err != nil {
1116			return nil, err
1117		}
1118		defer l.endOp()
1119	
1120		l.reg.mu.Lock()
1121		defer l.reg.mu.Unlock()
1122	
1123		results := runRefundBatch(batch, l.reg.state, l.persistEffect)
1124		return &RefundBatchResult{Results: results}, nil
1125	}
1126	
1127	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1128	
1129	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1130	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1131		return r.Account == it.Account &&
1132			r.Paymaster == it.Paymaster &&
1133			r.Asset == it.Asset &&
1134			r.Amount == amount &&
1135			r.Nonce == it.Nonce &&
1136			r.FeeBps == feeBps
1137	}
1138	
1139	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1140	func (l *Ledger) Query() (*Snapshot, error) {
1141		if err := l.beginOp(); err != nil {
1142			return nil, err
1143		}
1144		defer l.endOp()
1145		l.reg.mu.Lock()
1146		defer l.reg.mu.Unlock()
1147	
1148		st := l.stateView()
1149		bals := make([]BalanceView, 0, len(st.Balances))
1150		for k, v := range st.Balances {
1151			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1152		}
1153		sortBalances(bals)
1154		recs := make([]Record, len(st.Settlements))
1155		copy(recs, st.Settlements)
1156		refunds := make([]RefundRecord, len(st.Refunds))
1157		copy(refunds, st.Refunds)
1158		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1159	}
1160	
1161	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1162	func (l *Ledger) Balance(account, asset string) (int64, error) {
1163		if err := l.beginOp(); err != nil {
1164			return 0, err
1165		}
1166		defer l.endOp()
1167		l.reg.mu.Lock()
1168		defer l.reg.mu.Unlock()
1169		return l.stateView().Balances[balanceKey{account, asset}], nil
1170	}
1171	
1172	func sortBalances(bals []BalanceView) {
1173		sort.Slice(bals, func(i, j int) bool {
1174			if bals[i].Account != bals[j].Account {
1175				return bals[i].Account < bals[j].Account
1176			}
1177			return bals[i].Asset < bals[j].Asset
1178		})
1179	}
1180	
1181	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1182	func (l *Ledger) persistLocked() error {
1183		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1184			return ledgerError(ErrStorage, "injected write failure")
1185		}
1186		return atomicWrite(l.path, l.stateView())
1187	}
1188	
1189	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1190	func SetFailHook(l *Ledger, fw FailWriter) {
1191		l.reg.failHook = fw
1192	}
1193

