// 损坏检测：篡改退款相关语义均拒绝为损坏账本。
func TestCorruptRefundLedgerRejected(t *testing.T) {
	k := balanceKey{"aa", "usdc"}
	initial := map[balanceKey]int64{k: 1000}
	rec := Record{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 300, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 300, Seq: 1}
	goodRF := RefundRecord{ID: "r1", SettlementID: "p1", Reason: "x", Account: "aa", Asset: "usdc", Amount: 300, Fee: 0, Charged: 300, AfterSeq: 1, Seq: 1}
	finalBack := map[balanceKey]int64{k: 1000} // 退完回到初始

	mkRF := func(mut func(*RefundRecord)) []RefundRecord {
		r := goodRF
		mut(&r)
		return []RefundRecord{r}
	}

	cases := map[string]struct {
		final   map[balanceKey]int64
		records []Record
		refunds []RefundRecord
	}{
		"missing settlement": {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.SettlementID = "ghost" })},
		"double refund": {finalBack, []Record{rec}, []RefundRecord{
			goodRF,
			func() RefundRecord { r := goodRF; r.ID = "r2"; r.Seq = 2; return r }(),
		}},
		"amount differs":      {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Amount = 299; r.Charged = 299 })},
		"charged differs":     {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Charged = 301 })},
		"asset differs":       {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Asset = "eth" })},
		"empty reason":        {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Reason = "" })},
		"seq gap":             {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Seq = 2 })},
		"after_seq too large": {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.AfterSeq = 2 })},
		"balance mismatch":    {map[balanceKey]int64{k: 999}, []Record{rec}, mkRF(func(r *RefundRecord) {})},
	}

	// “duplicate refund id”：两笔不同结算各退一次，但两条退款记录共用编号 r1。
	rec2 := Record{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 1, Nonce: 2, FeeBps: 0, Fee: 0, Charged: 1, Seq: 2}
	rf2 := goodRF
	rf2.Seq = 2
	rf2.SettlementID = "p2"
	rf2.Amount, rf2.Fee, rf2.Charged = 1, 0, 1
	rf2.AfterSeq = 2
	cases["duplicate refund id"] = struct {
		final   map[balanceKey]int64
		records []Record
		refunds []RefundRecord
	}{
		final:   map[balanceKey]int64{k: 1000 - 1},
		records: []Record{rec, rec2},
		refunds: []RefundRecord{goodRF, rf2},
	}

	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			if err := validateAndReplay(initial, tc.final, tc.records, tc.refunds); err == nil || KindOf(err) != ErrCorrupt {
				t.Fatalf("%s: want ErrCorrupt, got %v", name, err)
			}
		})
	}

	// 健康的付款→退款账本必须通过。
	if err := validateAndReplay(finalBack, finalBack, []Record{rec}, []RefundRecord{goodRF}); err != nil {
		t.Fatalf("healthy refund ledger rejected: %v", err)
	}
}

// 损坏检测：退款成功顺序中的 after_seq 必须单调不减——付款历史只会追加，
// 后一笔退款落账时已存在的结算不可能比前一笔退款时更少。
func TestRefundAfterSeqRegressionRejected(t *testing.T) {
	k := balanceKey{"aa", "usdc"}
	initial := map[balanceKey]int64{k: 1000}
	p1 := Record{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 100, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 100, Seq: 1}
	p2 := Record{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 100, Nonce: 2, FeeBps: 0, Fee: 0, Charged: 100, Seq: 2}
	rf := func(id, sid string, afterSeq, seq int64) RefundRecord {
		return RefundRecord{ID: id, SettlementID: sid, Reason: "x", Account: "aa", Asset: "usdc", Amount: 100, Fee: 0, Charged: 100, AfterSeq: afterSeq, Seq: seq}
	}
	finalBack := map[balanceKey]int64{k: 1000} // 两笔各 100 全部退回

	// 任务示例：r1（seq 1）在已有 2 笔付款时退回 p2（after_seq=2），
	// r2（seq 2）却声称自己落账时只有 1 笔付款（after_seq=1）。
	// 金额、目标、各自序号与最终余额单独都能核对上，仍必须拒绝。
	err := validateAndReplay(initial, finalBack, []Record{p1, p2},
		[]RefundRecord{rf("r1", "p2", 2, 1), rf("r1-target", "p1", 1, 2)})
	if KindOf(err) != ErrCorrupt {
		t.Fatalf("regressing after_seq: want ErrCorrupt, got %v", err)
	}
	le := err.(*LedgerError)
	if !strings.Contains(le.Message, `"r1-target"`) || !strings.Contains(le.Message, `"r1"`) {
		t.Fatalf("error must name both adjacent refunds, got %q", le.Message)
	}

	// 规则针对整本账本的付款历史：两笔退款属于不同账户/资产同样不放行。
	kb := balanceKey{"bb", "usdc"}
	pb1 := Record{ID: "pb1", Account: "bb", Paymaster: "pm", Asset: "usdc", Amount: 100, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 100, Seq: 2}
	crossInitial := map[balanceKey]int64{k: 1000, kb: 1000}
	crossFinal := map[balanceKey]int64{k: 1000, kb: 1000}
	rfb := rf("rb", "pb1", 2, 1)
	rfb.Account = "bb"
	rfa := rf("ra", "p1", 1, 2)
	if err := validateAndReplay(crossInitial, crossFinal, []Record{p1, pb1},
		[]RefundRecord{rfb, rfa}); KindOf(err) != ErrCorrupt {
		t.Fatalf("cross-account regression: want ErrCorrupt, got %v", err)
	}

	// 相邻退款 after_seq 相等合法：两次退款之间没有新增成功付款。
	if err := validateAndReplay(initial, finalBack, []Record{p1, p2},
		[]RefundRecord{rf("r1", "p1", 2, 1), rf("r2", "p2", 2, 2)}); err != nil {
		t.Fatalf("equal after_seq must be accepted: %v", err)
	}

	// 正常交错历史：付款→退款→再付款→再退款，after_seq 递增。
	if err := validateAndReplay(initial, finalBack, []Record{p1, p2},
		[]RefundRecord{rf("r1", "p1", 1, 1), rf("r2", "p2", 2, 2)}); err != nil {
		t.Fatalf("interleaved history must be accepted: %v", err)
	}
}

